#!/usr/bin/env node
/**
 * Copy the built site from `site/dist/` into `docs/`, which is what GitHub
 * Pages publishes.
 *
 * Why this is not just `outDir: '../docs'`.
 *
 * `docs/` is not only a publish directory. It is also where several Markdown
 * files live that other parts of the repository point at by path, and Astro
 * empties its `outDir` before every build:
 *
 *   - `docs/api-contract/openapi.json` and `docs/api-contract/http.md` are
 *     generated by `implementation_scripts/api_contract.py` and guarded by
 *     `verification_scripts/test_api_contract.py`, which regenerates both and
 *     fails on any difference. A build that deleted them would turn a Python
 *     test red for a reason nobody would look for in a site build.
 *   - `docs/adding-a-source.md`, `docs/source-landscape.md`,
 *     `docs/local-api-security.md` and the rest are linked by repository path
 *     from `AGENTS.md` and from the source tree.
 *   - `docs/_posts/` holds the 27 posts. `AGENTS.md` lists that path as one
 *     Claude Code owns.
 *
 * So those files stay exactly where they are, the site reads them in place, and
 * this script copies the build output around them. PROTECTED below is the list,
 * and it is a list rather than "leave anything that is Markdown" because a
 * forgotten file is the failure mode worth designing against.
 *
 * Everything in `docs/` that is not protected is removed before the copy, so a
 * page that stops existing stops being published instead of lingering.
 *
 * Usage, from `site/`:   node scripts/sync-docs.mjs   (or `npm run build`)
 */
import {
  readdirSync,
  statSync,
  rmSync,
  mkdirSync,
  copyFileSync,
  existsSync,
  writeFileSync,
} from 'node:fs';
import { join, dirname, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const SITE = join(HERE, '..');
const DIST = join(SITE, 'dist');
const DOCS = join(SITE, '..', 'docs');

/**
 * Paths under `docs/`, relative and with forward slashes, that this script
 * never deletes. A trailing `/**` protects a whole subtree; a pattern with a
 * single `*` matches one path segment.
 */
const PROTECTED = [
  // The 27 published posts, read in place by the site's content loader.
  '_posts/**',
  // The generated, guarded API contract, plus its own explainer.
  'api-contract/*.md',
  'api-contract/*.json',
  // The reference documents, read in place and linked by repository path.
  '*.md',
];

function toPattern(pattern) {
  const escaped = pattern.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  const expanded = escaped.replace(/\*\*/g, '\u0000').replace(/\*/g, '[^/]*').replace(/\u0000/g, '.*');
  return new RegExp(`^${expanded}$`);
}

const PROTECTED_PATTERNS = PROTECTED.map((pattern) => toPattern(pattern.toLowerCase()));

/*
 * Matched case-insensitively, because the filesystem this runs on is. A build
 * file at `_POSTS/…` matched no pattern while resolving to the same inode as a
 * protected post, so the copy overwrote the post and the script exited 0 — the
 * collision guard below never saw it. A reviewer found that. Lowercasing both
 * sides costs nothing and removes the whole class.
 */
const isProtected = (relativePath) =>
  PROTECTED_PATTERNS.some((pattern) => pattern.test(relativePath.toLowerCase()));

function walk(root, prefix = '') {
  const out = [];
  for (const name of readdirSync(join(root, prefix))) {
    const relativePath = prefix ? `${prefix}/${name}` : name;
    const full = join(root, relativePath);
    if (statSync(full).isDirectory()) out.push(...walk(root, relativePath));
    else out.push(relativePath);
  }
  return out;
}

function removeEmptyDirectories(root, prefix = '') {
  const here = join(root, prefix);
  for (const name of readdirSync(here)) {
    const relativePath = prefix ? `${prefix}/${name}` : name;
    if (statSync(join(root, relativePath)).isDirectory()) removeEmptyDirectories(root, relativePath);
  }
  if (prefix && readdirSync(here).length === 0) rmSync(here, { recursive: true });
}

if (!existsSync(DIST)) {
  process.stderr.write('sync-docs: site/dist does not exist — run `astro build` first\n');
  process.exit(1);
}

mkdirSync(DOCS, { recursive: true });

// ---- 1. Clear the previous output, keeping the protected sources -----------

const existing = walk(DOCS);
const built = walk(DIST);
const builtPaths = new Set(built);

const keptPaths = existing.filter((relativePath) => isProtected(relativePath));
const doomed = existing.filter((relativePath) => !isProtected(relativePath));

/*
 * Say what is being deleted before deleting it.
 *
 * `PROTECTED` is a list, and the failure this script is designed against is a
 * file somebody adds to `docs/` later and forgets to add to the list. Deleting
 * quietly is exactly what hides that: a reviewer planted
 * `docs/api-contract/openapi.yaml` and `docs/api-contract/schemas/paper.json`,
 * both were removed, the preserved count did not move, and the run exited 0.
 *
 * A file the build is about to replace is ordinary and not worth a line. A file
 * that is being removed and *not* replaced is the interesting case, and every
 * one of those is named here. The script still proceeds — refusing would make
 * deleting a page impossible — but the deletion is now in the run's output
 * where a person or a diff can see it. Anything named here that should have
 * survived belongs in `PROTECTED`.
 */
const orphans = doomed.filter((relativePath) => !builtPaths.has(relativePath));
if (orphans.length) {
  process.stdout.write(
    `sync-docs: removing ${orphans.length} file(s) in docs/ that this build does not replace ` +
      'and PROTECTED does not cover:\n',
  );
  for (const relativePath of orphans) process.stdout.write(`  - ${relativePath}\n`);
  process.stdout.write(
    '  If any of those should have survived, add it to PROTECTED in this script.\n',
  );
}

let removed = 0;
for (const relativePath of doomed) {
  rmSync(join(DOCS, relativePath));
  removed += 1;
}
const kept = keptPaths.length;
removeEmptyDirectories(DOCS);

// ---- 2. Copy the build output ---------------------------------------------

const collisions = [];
for (const relativePath of built) {
  if (isProtected(relativePath)) {
    // The build must not try to write over a file this script is pledged to
    // keep. If it ever does, the two have the same name for a reason worth
    // understanding, so stop rather than pick a winner.
    collisions.push(relativePath);
    continue;
  }
  const target = join(DOCS, relativePath);
  mkdirSync(dirname(target), { recursive: true });
  copyFileSync(join(DIST, relativePath), target);
}

if (collisions.length) {
  process.stderr.write(
    `sync-docs: the build wrote ${collisions.length} file(s) at protected paths:\n` +
      collisions.map((p) => `  ${p}\n`).join(''),
  );
  process.exit(1);
}

// ---- 3. .nojekyll ----------------------------------------------------------

/*
 * Without this file GitHub Pages runs Jekyll over whatever is in `docs/`, which
 * would take a built static site and try to build it again. It is also what
 * makes paths beginning with an underscore servable, which `docs/_posts/`
 * needs. It is written here rather than only in `public/` so that the file is
 * guaranteed present even if someone copies `dist/` by hand.
 */
writeFileSync(join(DOCS, '.nojekyll'), '', 'utf8');

const relDocs = relative(join(SITE, '..'), DOCS).split(sep).join('/');
process.stdout.write(
  `sync-docs: ${built.length} file(s) copied into ${relDocs}/, ` +
    `${removed} stale file(s) removed, ${kept} source file(s) preserved\n`,
);
